import {ENDING_STORIES} from './endings.js';
import {ART,sceneSVG,portraitStyle} from './art.js';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function sea(){return`<svg viewBox="0 0 720 380" role="img" aria-label="主角幻想中的清晨海邊"><defs><linearGradient id="endingSky" x2="0" y2="1"><stop stop-color="#a8c0c8"/><stop offset="1" stop-color="#f2d9b4"/></linearGradient></defs><rect width="720" height="380" fill="url(#endingSky)"/><circle cx="500" cy="125" r="44" fill="#f7e1aa"/><path d="M0 180Q170 165 360 185T720 180V380H0Z" fill="#6d9fa5"/><path d="M0 230Q180 210 360 230T720 225M0 280Q180 258 360 280T720 275" stroke="#cce1d6" stroke-width="3" fill="none"/><path d="M0 330Q320 260 720 305V380H0Z" fill="#d9c5a0"/><text x="36" y="346" fill="#496b70" font-size="15" letter-spacing="5">NEXT STOP / 海邊</text></svg>`;}
function prop(theme){return`<div class="ending-prop" aria-hidden="true">${theme==='warm'?'<span class="ending-breakfast">☕</span><b>早餐，還是熱的。</b>':theme==='meal'?'<span class="ending-lunchbox">▤</span><b>冰箱裡，還有一個人等你。</b>':theme==='lift'?'<div class="ending-lift-doors"><i></i><i></i></div><b>電梯即將關門——</b>':'<b>您撥的ENT暫時無法接聽。</b>'}</div>`;}
export function endingHTML(e,{name='小值',character='male'}={}){
 const story=ENDING_STORIES.find(s=>s.id===e.storyId);
 if(e.montage)return`<div class="ending-montage"><header><span>ORIGINAL SONG / 原創歌曲</span><h2 id="modalTitle">天亮以前</h2><p>這一班的聲音，慢慢變成了一首歌。</p></header><div class="ending-memory-grid">${e.memories.map(m=>`<article><div>${sceneSVG(m.scene)}</div><section><h3>${esc(m.title)}</h3><p>${esc(m.text)}</p></section></article>`).join('')}</div><div class="ending-montage-actions"><button id="endingAudio" class="secondary-button">暫停／繼續片尾曲 ♫</button><button id="endingReveal" class="primary-button">揭曉這一班的分數與封號 →</button></div><p id="endingAudioStatus" class="small-note" role="status">可留在這裡聽歌，也可直接揭曉結果。</p></div>`;
 const step=e.step,title=step===0?'07:30，天亮了。':step===1?story.theme==='sea'?'喂？喂……？':'以為終於能走了。':story.title;
 const copy=step===0?'窗外慢慢亮了。你把手邊的東西收好，肩膀終於鬆了一點。':step===1?story.phone:story.last;
 return`<div class="ending-cinema theme-${story.theme}"><div class="ending-cinema-scene">${step===2&&story.theme==='sea'?sea():sceneSVG(step===0?5:story.scene)}<div class="ending-cinema-shade"></div>${!(step===2&&story.theme==='sea')?`<div class="ending-resident portrait-avatar" style="background-image:url('${ART.characters[character].portraits}');${portraitStyle(step===0?4:story.face)}"></div>`:''}<div class="ending-cinema-caption"><span>ENT ON CALL / ${step===0?'DAWN':step===1?'ONE LAST CALL':'THE END'}</span><b>${esc(name)} · ENT R</b></div>${step===1?'<div class="ending-phone-signal">☎<span>最後一通電話</span></div>':''}</div><section class="ending-cinema-copy"><span class="ending-chapter">${step+1} / 3 · 天亮以後</span><h2 id="modalTitle">${esc(title)}</h2><p class="ending-dialogue">${esc(copy)}</p>${step===2?'<p class="ending-thought">'+esc(story.thought)+'</p>'+prop(story.theme):''}<div class="ending-navigation"><button id="endingPrevious" class="text-button" ${step===0?'disabled':''}>← 上一幕</button><button id="endingNext" class="primary-button">${step===0?'電話響了，接起來 →':step===1?'接下來呢 →':'讓這一班慢慢淡出 ♫'}</button></div></section></div>`;
}
